(function(){angular.module("app.core").directive("msCard",msCardDirective);function msCardDirective(){return{restrict:"E",scope:{templatePath:"=template",card:"=ngModel",vm:"=viewModel"},template:'<div class="ms-card-content-wrapper" ng-include="templatePath" onload="cardTemplateLoaded()"></div>',compile:function(tElement){tElement.addClass("ms-card");
return function postLink(scope,iElement){scope.cardTemplateLoaded=cardTemplateLoaded;function cardTemplateLoaded(){scope.$emit("msCard::cardTemplateLoaded",iElement)}}}}}})();